function applyLearning(d){state.lang=d.lang==='zh'?'zh':'en';progress=d.progress&&typeof d.progress==='object'?d.progress:{};revived=Array.isArray(d.revived)?d.revived:[];quizOrders=d.quizOrders&&typeof d.quizOrders==='object'?d.quizOrders:{};state.id=letters.some(l=>l.id===d.id)?d.id:1;state.chapter=Math.max(0,Math.min(chapters.length-1,Number(d.chapter)||0));state.explorer=!C().ids.includes(state.id)}
