function introThen(id,next){const screen=state.screen,tab=state.tab,letter=state.id;let done=false,wait;
 const watch=({detail})=>{if(detail.id===id&&detail.phase==='playing')clearTimeout(wait)};
 const go=()=>{if(done)return;done=true;clearTimeout(wait);document.removeEventListener?.('teacher-voice-state',watch);if(next&&state.screen===screen&&state.tab===tab&&state.id===letter)next()};
 document.addEventListener?.('teacher-voice-state',watch);wait=setTimeout(go,6000);
 TeacherVoice.play(id,null,null,1,go).then(ok=>{if(!ok)go()})}
// The map's prompt waits while an island is waking up (that animation has its own voice).
function goMap(){stopSound();state.screen='home';render();if(!$('.island.reviving'))introThen('intro-map')}
function pagePrompt(){if(state.screen==='home')return 'intro-map';if(state.screen==='library')return 'intro-library';if(state.screen==='complete')return 'island-done';
 if(state.tab==='learn')return `explain-${state.id}`;if(state.tab==='write')return 'hint-write';if(quiz?.words)return wordsDone()?'words-done':'intro-words';return 'hint-play'}
