function goLetter(id,explorer=false){stopSound();revealedLetter=null;state.id=id;state.explorer=explorer;state.screen='lesson';state.tab='learn';state.stage='trace';quiz=null;demoTime=0;demoPlaying=true;persist();render();introThen(`explain-${id}`,()=>playLetter({currentTarget:$('#listen')}))}
