// Reward layer sits above the page so a re-render never cuts an animation short.
function cheer(from,kind,text){const r=from.getBoundingClientRect(),x=r.left+r.width/2,y=r.top+r.height/2,still=matchMedia('(prefers-reduced-motion: reduce)').matches;
 if(kind==='yay'){let banner=document.createElement('div');banner.className='cheer-banner';banner.innerHTML=`<span aria-hidden="true">🎉</span>${text||t('You did it!','太棒了！')}`;document.body.append(banner);setTimeout(()=>banner.remove(),1700);
  if(!still)for(let i=0;i<22;i++){let bit=document.createElement('span'),a=Math.PI*2*i/22+Math.random()*.3,d=110+Math.random()*120;bit.className='confetti';bit.textContent=['★','●','♥','✿'][i%4];bit.style.cssText=`left:${x}px;top:${y}px;color:${['#e5b34f','#8fb36a','#e88d74','#7ea7c9','#b38bd0'][i%5]};--x:${Math.cos(a)*d}px;--y:${Math.sin(a)*d-60}px;--r:${Math.random()*540-270}deg`;document.body.append(bit);setTimeout(()=>bit.remove(),1300)}}
 else{let bubble=document.createElement('div');bubble.className='try-bubble';bubble.innerHTML=`${t('Try again!','再試一次！')} <span aria-hidden="true">💪</span>`;bubble.style.left=x+'px';bubble.style.top=r.top+'px';document.body.append(bubble);setTimeout(()=>bubble.remove(),1300)}}
function bindQuiz(){const shown=quiz;if(shown&&!shown.revealed){clearTimeout(shown.fallback);shown.fallback=setTimeout(()=>{if(quiz===shown&&state.tab==='play'&&state.screen==='lesson')revealQuizCards(shown)},3000)}$('#quiz-listen').onclick=playQuizPrompt;$$('[data-answer]').forEach(b=>b.onclick=()=>{const q=quiz,id=+b.dataset.answer;if(!q.revealed){playQuizPrompt();return}if(!q.ready)return;if(q.solved||q.locked||q.wrong.includes(id))return;q.locked=true;setTimeout(()=>q.locked=false,700);
 if(id===state.id){q.solved=true;mark('quiz');TeacherVoice.effect('yay');b.classList.add('correct','pop');$$('[data-answer]').forEach(o=>o!==b&&o.classList.add('fade-out'));$('.quiz-picture')?.classList.add('dance');$('.coach-face')?.classList.add('jump');cheer(b,'yay');$('#feedback').textContent=t('You found it! ★','找到了！★');setHint(t('Lovely work! Now meet three more words.','做得好！再認識三個單字吧。'));setTimeout(()=>{if(quiz===q&&state.tab==='play')TeacherVoice.play('well-done')},800);wordIds().forEach(TeacherVoice.prefetch);setTimeout(()=>{if(quiz===q&&state.tab==='play'&&state.screen==='lesson')showWords(q)},2600)}
 else{q.tries++;q.wrong.push(id);TeacherVoice.effect('oops');b.classList.add('try-again');cheer(b,'oops');$('#feedback').textContent=t('Good try. Listen once more!','很棒的嘗試，再聽一次吧！');setTimeout(()=>{b.classList.remove('try-again');b.classList.add('used');b.disabled=true},650);
  if(q.tries===1){setHint(t('Need help? Tap Hint and look for the glowing letter.','需要幫忙嗎？點「提示」，找找發亮的字母。'));setTimeout(()=>{if(quiz===q&&!q.solved&&state.tab==='play')TeacherVoice.play('try-again')},700)}
  else{$(`[data-answer="${state.id}"]`)?.classList.add('hint-answer');setHint(t('Look! The glowing letter is my friend.','看！發亮的字母就是我的朋友。'))}}})}
async function parents(){const d=$('#help');d.innerHTML=`<div class="dialog-head"><h2>${t('For grown-ups','家長設定')}</h2><button id="close-help" aria-label="Close">×</button></div><div class="dialog-actions"><button id="language" class="dialog-button">${t('Show hints in 中文','提示改用 English')}</button></div>${accountSection()}<h3>${t('A little, every day','每天一小步')}</h3><p>${t('Try one letter for 5–10 minutes. Listen → write → play. Give encouragement, not a score. There are 16 starter letters and 44 letters to explore.','每次花 5–10 分鐘學一個字母：聽 → 寫 → 玩。給孩子鼓勵，不必評分。入門有 16 個字母，探索區有全部 44 個。')}</p><button id="all-letters" class="dialog-button">${t('Explore all 44 letters','探索全部 44 個字母')} →</button><h3>${t('Teacher voice','老師語音')}</h3><p id="api-state">${t('Checking voice connection…','檢查語音連線中…')}</p><p>${t('The natural teacher voice is AI-generated. Only fixed lesson scripts are sent to the speech service. Speaking practice listens for up to 6 seconds with the device’s built-in dictation, which Apple processes and may send to its servers. Thai Sprout does not upload or keep recordings. Original Thai recordings are available as a backup.','自然老師語音由 AI 產生，只傳送固定教材文字給語音服務。跟讀練習每次最多聽 6 秒，使用裝置內建聽寫，由 Apple 處理並可能傳送到 Apple 伺服器；Thai Sprout 不上傳、不保存錄音。泰語原聲錄音可作備用。')}</p><div class="dialog-actions"><button class="dialog-button" id="speech-setup">${t('Speaking practice setup','跟讀練習設定')}</button><button class="dialog-button" id="install-app">${t('Add to Home Screen','加入主畫面')}</button></div><h3>${t('Learning notes','教學提醒')}</h3><p>${t('This introduces consonants. Picture words name letters; the letter does not always appear first. ฃ and ฅ are historical letters. Tracing is a shape guide; use the animation for direction. Drawing is practice, not automatic handwriting grading.','這是子音入門，圖像詞用來命名字母，目標字母不一定在詞的開頭。ฃ、ฅ 為歷史字母。描字供認形，書寫方向請看動畫。手寫區提供練習，不會自動評分筆順。')}</p><p>${member?t('Progress is saved to the Google account and this browser. Drawings clear when the page reloads.','進度保存在 Google 帳號與這個瀏覽器，重新整理會清除筆跡。'):t('Progress is saved in this browser. Drawings clear when the page reloads.','進度保存在這個瀏覽器，重新整理會清除筆跡。')}</p><p><a href="https://seasite.niu.edu/Thai/basic/alpha_cons_table.htm" target="_blank" rel="noopener">${t('Writing models & original Thai audio: NIU SEAsite','書寫示範與泰語原聲：NIU SEAsite')}</a></p><p class="made-by">${t('Made by the studio','開發工作室：')} <a href="https://oceanads.org" target="_blank" rel="noopener">OceanAds</a> · <a href="mailto:support@oceanads.org">support@oceanads.org</a><br><a href="terms.html?lang=${state.lang}" target="_blank" rel="noopener">${t('Terms of Use','服務條款')}</a> · <a href="privacy.html?lang=${state.lang}" target="_blank" rel="noopener">${t('Privacy Policy','隱私權政策')}</a></p><button id="reset" class="dialog-button">${member?t('Reset this member’s progress…','重設這位會員的學習進度…'):t('Reset this browser’s progress…','重設這個瀏覽器的學習進度…')}</button>`;
 $('#speech-setup').onclick=()=>{d.close();SpeechPractice.setup()};$('#install-app').onclick=()=>{d.close();SproutPWA.guide()};$('#close-help').onclick=()=>d.close();$('#language').onclick=()=>{state.lang=state.lang==='en'?'zh':'en';langChosen=true;persist();d.close();render()};$('#all-letters').onclick=()=>{d.close();state.screen='library';render();introThen('intro-library')};$('#reset').onclick=()=>{if(confirm(t('Reset learning progress?','要重設學習進度嗎？'))){progress={};revived=[];quizOrders={};saveLocal();window.SproutAccount?.reset(learning());d.close();render()}};if($('#sign-out'))$('#sign-out').onclick=signOut;if(!d.open)d.showModal();const status=await TeacherVoice.status();const el=$('#api-state');if(el)el.textContent=status.configured?t('API key is configured. Tap a lesson sound to check playback.','API 金鑰已設定，點課程語音可測試播放。'):t('Teacher API voice is not activated yet. Add OPENROUTER_API_KEY in this Netlify project and redeploy. Thai backup recordings still work.','API 老師語音尚未啟用。請在這個 Netlify 專案加入 OPENROUTER_API_KEY 並重新部署；泰語備用錄音仍可使用。');
}
function init(){document.addEventListener('teacher-voice-state',updateLetterCard);document.addEventListener('teacher-voice-state',updateQuizCards);document.addEventListener('teacher-voice-state',updateWordCards);fetch('assets/writing.json?v=2').then(r=>r.json()).then(data=>{meta=data;paintDemo();drawPad()}).catch(()=>toast(t('Connect to the internet to load the writing demo.','請連上網路以載入書寫示範。')));document.fonts?.ready.then(()=>drawPad());document.addEventListener('visibilitychange',()=>{if(document.hidden)stopSound()});matchMedia('(orientation: portrait) and (pointer: coarse)').addEventListener?.('change',e=>{if(e.matches)stopSound()});render();requestAnimationFrame(tick);
 const login=new URLSearchParams(location.search).get('login');if(login){history.replaceState(null,'',location.pathname);toast(t('Sign-in did not finish. Please try again.','登入沒有完成，請再試一次。'))}
 window.SproutAccount?.onChange(kind=>{if(kind==='failed'){toast(t('Sign-in did not finish. Please try again.','登入沒有完成，請再試一次。'));return}syncAccount().then(()=>{if(member)toast(t(`Welcome, ${member.name}! Your islands are saved.`,`歡迎，${member.name}！小島進度已保存。`))})});syncAccount()}
